/**
 * IngestHealthResponse
 *
 * Aggregate ingest-status counts across the deployment.
 *
 * The four document-level buckets sum to roughly the document count
 * (rows in ``documents``); ``parse_failed`` reports file-level
 * failures (rows in ``files`` with ``ingestion_status='failed'``),
 * which never reach the ``documents`` table.
 *
 * Operators use this surface as the canonical "is my ingest healthy?"
 * signal — a non-zero ``embed_failed`` or ``partial`` count is the
 * silent-degrade signal that triggered DE-276; a non-zero
 * ``parse_failed`` count is the operator's cue to inspect specific
 * files via the existing file-list UI.
 */
export type IngestHealthResponse = {
    /**
     * Ok
     *
     * Documents with all chunks successfully embedded.
     */
    ok: number;
    /**
     * Embed Failed
     *
     * Documents whose embed worker raised before any chunk was embedded — hybrid retrieval degrades to FTS-only for these.
     */
    embed_failed: number;
    /**
     * Partial
     *
     * Documents whose embed worker raised mid-batch — some chunks have vectors, others are NULL. Operators may re-run ingest to recover.
     */
    partial: number;
    /**
     * Parse Failed
     *
     * Files that failed at parse time and never produced a documents row (``files.ingestion_status='failed'``).
     */
    parse_failed: number;
    /**
     * Total Documents
     *
     * Total rows in the documents table (sum of ok + embed_failed + partial).
     */
    total_documents: number;
};

